/**
 * Flight detection for calendar events.
 *
 * Handles the two shapes that show up in real calendars:
 *   - Generated by Gmail/airlines: "Flight to Faro (FR 123)", with the departure
 *     airport in LOCATION and often a "Dublin (DUB) to Faro (FAO)" line in the notes.
 *   - Typed by hand: "Flight to Paris", "Fly home", "EI204 DUB ORD", "Dublin to London".
 *
 * Endpoints are resolved from SUMMARY first, then DESCRIPTION, then LOCATION (as the
 * departure airport). A side that cannot be resolved stays "???" with a warning; when the
 * place is known but has several airports ("London") its name is kept so the entry is
 * still readable.
 */
import { airportByCode, isAirportCode, resolveAirportText } from "../../airports";

export interface FlightEndpoint {
  /** IATA code when resolved. */
  code?: string;
  /** Place text from the event when it could not be resolved to one airport. */
  name?: string;
  /** Candidate airports when the place has several. */
  candidates?: string[];
}

export interface FlightInfo {
  from: FlightEndpoint;
  to: FlightEndpoint;
  flightNumber?: string;
  warnings: string[];
}

export interface FlightInput {
  summary: string;
  location?: string;
  description?: string;
}

/** Uppercase words that look like airport codes but are not. */
const CODE_IGNORE = new Set([
  "MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN",
  "JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC",
  "THE", "AND", "FOR", "VIA", "UTC", "GMT", "BST", "CET", "EST", "PST", "NEW", "ALL",
]);

/** Airline designators that contain a digit; anything else with a digit is not a flight number. */
const DIGIT_AIRLINES = new Set([
  "U2", "W6", "5J", "4U", "9W", "B6", "F9", "G3", "G4", "3K", "6E", "7C", "I2", "D8", "X3", "S7", "H2", "E5", "VY",
]);

const FLIGHT_WORD_RE = /\b(flights?|fly|flying)\b/i;

/** Rail wording and service prefixes, so "ICE 1234 Berlin → Hamburg" is never read as a flight. */
const TRAIN_RE =
  /\b(train|rail|eurostar|tgv|intercity|amtrak|sprinter|sleeper)\b|\b(IC|ICE|EC|EN|RE|RB|TER|AVE|ITA)\s?\d+\b/i;

// Case-sensitive on purpose: "to 23" in prose must not read as a flight number.
const FLIGHT_NUM_RE = /\b([A-Z]{2,3}|[A-Z][0-9]|[0-9][A-Z])\s?(\d{2,4})\b/g;

export function extractFlightNumber(text: string): { value: string; span: [number, number] } | undefined {
  FLIGHT_NUM_RE.lastIndex = 0;
  let m: RegExpExecArray | null;
  while ((m = FLIGHT_NUM_RE.exec(text)) !== null) {
    const airline = m[1];
    if (/\d/.test(airline) && !DIGIT_AIRLINES.has(airline)) continue;
    // A real airport code followed by digits is more likely "DUB 12" noise than a flight.
    if (airline.length === 3 && isAirportCode(airline)) continue;
    return { value: `${airline}${m[2]}`, span: [m.index, m.index + m[0].length] };
  }
  return undefined;
}

function blank(text: string, span?: [number, number]): string {
  return span ? text.slice(0, span[0]) + " ".repeat(span[1] - span[0]) + text.slice(span[1]) : text;
}

/** Valid airport codes in order of appearance, without duplicates. */
function codesIn(text: string): string[] {
  const out: string[] = [];
  for (const m of text.matchAll(/\b[A-Z]{3}\b/g)) {
    const code = m[0];
    if (CODE_IGNORE.has(code) || !isAirportCode(code) || out.includes(code)) continue;
    out.push(code);
  }
  return out;
}

const ARROW = String.raw`(?:→|->|—|–|>|\bto\b|-)`;

function endpointFromText(raw: string): FlightEndpoint | undefined {
  let t = raw
    .replace(/\([^)]*\)/g, " ") // "(FR 123)" and "(DUB)" are handled elsewhere
    .replace(FLIGHT_WORD_RE, " ")
    .replace(/\b(from|home|back|return|outbound|inbound|departing|arriving|arrival|departure|at|the|my)\b/gi, " ")
    .replace(/[^\p{L}\p{N}\s'’.-]/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!t || t.length < 3) return undefined;
  // Drop a trailing time like "10:30" that survived punctuation stripping.
  t = t.replace(/\b\d{1,2}\s?(am|pm)?\b$/i, "").trim();
  if (!t) return undefined;
  const r = resolveAirportText(t);
  if (r.code) return { code: r.code };
  if (r.candidates.length > 1) return { name: t, candidates: r.candidates };
  return undefined;
}

interface Route { from?: FlightEndpoint; to?: FlightEndpoint }

/** Pull a route out of one block of text. */
function routeIn(text: string): Route {
  if (!text.trim()) return {};
  const num = extractFlightNumber(text);
  const clean = blank(text, num?.span);

  // 1. "DUB → FAO", "DUB-FAO", "DUB to FAO"
  const pair = new RegExp(String.raw`\b([A-Z]{3})\s*${ARROW}\s*([A-Z]{3})\b`, "i").exec(clean);
  if (pair) {
    const a = pair[1].toUpperCase();
    const b = pair[2].toUpperCase();
    if (isAirportCode(a) && isAirportCode(b) && !CODE_IGNORE.has(a) && !CODE_IGNORE.has(b) && a !== b) {
      return { from: { code: a }, to: { code: b } };
    }
  }

  // 2. Codes anywhere, in order: "Dublin (DUB) to Faro (FAO)", "EI204 DUB ORD"
  const codes = codesIn(clean);
  if (codes.length >= 2) return { from: { code: codes[0] }, to: { code: codes[1] } };

  // 3. Place names around an arrow or "to": "Dublin to London", "Flight from Dublin to Faro"
  const around = new RegExp(String.raw`^(.*?)\s*${ARROW}\s*(.+)$`, "i").exec(clean.trim());
  if (around && around[1].trim()) {
    const from = endpointFromText(around[1]);
    const to = endpointFromText(around[2]);
    if (from || to) return { from, to };
  }

  // 4. Destination only: "Flight to Faro", "Fly to Paris (BA 304)"
  const toOnly = new RegExp(String.raw`\b(?:flights?|fly|flying)\b.*?\bto\b\s+(.+)$`, "i").exec(clean);
  if (toOnly) {
    const to = endpointFromText(toOnly[1]);
    if (to) return { to };
  }

  // 5. Origin only: "Flight from Dublin"
  const fromOnly = /\bfrom\b\s+(.+)$/i.exec(clean);
  if (fromOnly) {
    const from = endpointFromText(fromOnly[1]);
    if (from) return { from };
  }

  // A single code in parentheses is still a useful anchor: "Flight to Faro (FAO)".
  if (codes.length === 1 && /\bto\b/i.test(clean)) return { to: { code: codes[0] } };
  if (codes.length === 1) return { from: { code: codes[0] } };
  return {};
}

/** LOCATION is the departure airport on generated flight events. */
function originFromLocation(location: string): FlightEndpoint | undefined {
  const text = location.trim();
  if (!text) return undefined;
  const parenthesised = /\(([A-Z]{3})\)/.exec(text);
  if (parenthesised && isAirportCode(parenthesised[1])) return { code: parenthesised[1] };
  const r = resolveAirportText(text.split(",")[0]);
  return r.code ? { code: r.code } : undefined;
}

const resolved = (e?: FlightEndpoint) => !!e?.code;

/**
 * Decide whether an event is a flight and extract its route.
 * Returns null when the SUMMARY gives no flight signal, so ordinary events are untouched.
 */
export function parseFlight(input: FlightInput): FlightInfo | null {
  const { summary, location = "", description = "" } = input;

  const summaryRoute = routeIn(summary);
  const number = extractFlightNumber(summary) ?? extractFlightNumber(description);
  const summaryCodes = codesIn(blank(summary, extractFlightNumber(summary)?.span));

  const anchored = (e?: FlightEndpoint) => !!e?.code || !!e?.candidates?.length;
  const isFlight =
    FLIGHT_WORD_RE.test(summary) ||
    summaryCodes.length >= 2 ||
    (!!extractFlightNumber(summary) &&
      !TRAIN_RE.test(summary) &&
      (anchored(summaryRoute.from) || anchored(summaryRoute.to)));
  if (!isFlight) return null;

  const descRoute = description ? routeIn(description) : {};
  const origin = originFromLocation(location);

  let from = summaryRoute.from ?? (resolved(descRoute.from) ? descRoute.from : undefined) ?? origin ?? descRoute.from;
  let to = summaryRoute.to ?? descRoute.to;

  // A destination cannot also be the origin.
  if (from?.code && to?.code && from.code === to.code) from = undefined;

  const warnings: string[] = [];
  const ambiguous = (e: FlightEndpoint | undefined, label: string) => {
    if (e && !e.code && e.candidates?.length) {
      const list = e.candidates.slice(0, 5).join(", ");
      warnings.push(`${label} "${e.name}" has several airports (${list}) — choose one`);
    }
  };
  if (!resolved(from) && !resolved(to)) {
    warnings.push("No airport codes found — fill in From/To before confirming");
    ambiguous(from, "From");
    ambiguous(to, "To");
  } else {
    if (!resolved(from)) {
      warnings.push("Departure airport not found — fill in From");
      ambiguous(from, "From");
    }
    if (!resolved(to)) {
      warnings.push("Arrival airport not found — fill in To");
      ambiguous(to, "To");
    }
  }

  return { from: from ?? {}, to: to ?? {}, flightNumber: number?.value, warnings };
}

/** Airport timezone for a resolved endpoint. */
export function endpointTimezone(e: FlightEndpoint): string | undefined {
  return e.code ? airportByCode(e.code)?.timezone : undefined;
}
